CREATE OR REPLACE FUNCTION public.set_business_member_permissions(_workspace uuid,_user uuid,_permissions jsonb,_manage_trips boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE m public.workspace_members; BEGIN IF auth.uid() IS NULL OR NOT public.network_workspace_access(_workspace,true) OR coalesce(public.workspace_role_of(_workspace,auth.uid())::text,'') NOT IN ('owner','admin') THEN RAISE EXCEPTION 'Account owner or admin required'; END IF; SELECT * INTO m FROM public.workspace_members WHERE workspace_id=_workspace AND user_id=_user FOR UPDATE; IF NOT FOUND OR m.role IN ('owner','admin') OR m.is_contractor THEN RAISE EXCEPTION 'Only ordinary team member permissions may be changed'; END IF; IF jsonb_typeof(_permissions)<>'object' OR EXISTS(SELECT 1 FROM jsonb_each_text(_permissions) p WHERE p.key NOT IN ('vehicles','drivers','contacts','payers') OR p.value NOT IN ('none','read','manage')) THEN RAISE EXCEPTION 'Invalid business permissions'; END IF; UPDATE public.workspace_members SET record_permissions=_permissions,can_manage_trips=_manage_trips WHERE id=m.id; END $$;
REVOKE ALL ON FUNCTION public.set_business_member_permissions(uuid,uuid,jsonb,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.set_business_member_permissions(uuid,uuid,jsonb,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.guard_business_record_links() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_TABLE_NAME='vehicles' THEN IF NEW.assigned_driver_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.drivers WHERE id=NEW.assigned_driver_id AND workspace_id=NEW.workspace_id) THEN RAISE EXCEPTION 'Driver must belong to this business'; END IF; IF NEW.wheelchair_capacity IS NOT NULL AND NEW.wheelchair_capacity<0 THEN RAISE EXCEPTION 'Wheelchair positions cannot be negative'; END IF; ELSIF TG_TABLE_NAME='drivers' THEN IF NEW.primary_vehicle_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.vehicles WHERE id=NEW.primary_vehicle_id AND workspace_id=NEW.workspace_id) THEN RAISE EXCEPTION 'Vehicle must belong to this business'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER z_guard_business_record_links BEFORE INSERT OR UPDATE ON public.vehicles FOR EACH ROW EXECUTE FUNCTION public.guard_business_record_links();
CREATE TRIGGER z_guard_business_record_links BEFORE INSERT OR UPDATE ON public.drivers FOR EACH ROW EXECUTE FUNCTION public.guard_business_record_links();
CREATE OR REPLACE FUNCTION public.network_set_service_base(_workspace uuid,_address text,_lat double precision,_lng double precision,_services text[],_expires timestamptz DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_master_admin(auth.uid()) THEN RAISE EXCEPTION 'Only the Master Admin may verify service locations and capabilities'; END IF; IF _lat NOT BETWEEN -90 AND 90 OR _lng NOT BETWEEN -180 AND 180 OR _lat IS NULL OR _lng IS NULL OR length(trim(_address))=0 OR EXISTS(SELECT 1 FROM unnest(_services) s WHERE s NOT IN ('ambulatory','wheelchair','stretcher')) THEN RAISE EXCEPTION 'Verified coordinates and approved services required'; END IF; UPDATE public.provider_network_profiles SET service_base_address=_address,service_base_lat=_lat,service_base_lng=_lng,service_base_verified_at=now(),approved_service_types=_services,eligibility_expires_at=_expires WHERE workspace_id=_workspace; IF NOT FOUND THEN RAISE EXCEPTION 'Provider must complete its network profile first'; END IF; END $$;
REVOKE ALL ON FUNCTION public.network_set_service_base(uuid,text,double precision,double precision,text[],timestamptz) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.network_set_service_base(uuid,text,double precision,double precision,text[],timestamptz) TO authenticated;
CREATE OR REPLACE FUNCTION public.network_list_eligibility() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_master_admin(auth.uid()) THEN RAISE EXCEPTION 'Master Admin required'; END IF; RETURN(SELECT coalesce(jsonb_agg(jsonb_build_object('workspace_id',w.id,'business_name',w.display_name,'mfn_id',w.mfn_id,'address',p.service_base_address,'lat',p.service_base_lat,'lng',p.service_base_lng,'verified_at',p.service_base_verified_at,'services',p.approved_service_types,'expires_at',p.eligibility_expires_at)),'[]') FROM public.workspaces w JOIN public.provider_network_profiles p ON p.workspace_id=w.id WHERE w.account_type='provider' AND NOT w.is_test_account); END $$;
REVOKE ALL ON FUNCTION public.network_list_eligibility() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.network_list_eligibility() TO authenticated;
CREATE OR REPLACE FUNCTION public.network_offer_safe_history(_offer uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.network_offer_access(_offer) THEN RAISE EXCEPTION 'Offer unavailable'; END IF; RETURN(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'side',side,'action',action,'amount_cents',amount_cents,'business_note',business_note,'expires_at',expires_at,'created_at',created_at) ORDER BY created_at),'[]') FROM public.trip_offer_negotiations WHERE offer_id=_offer); END $$;
REVOKE ALL ON FUNCTION public.network_offer_safe_history(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.network_offer_safe_history(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.guard_distribution_source() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.request_id IS DISTINCT FROM OLD.request_id OR NEW.source_workspace_id IS DISTINCT FROM OLD.source_workspace_id OR NEW.original_person_id IS DISTINCT FROM OLD.original_person_id OR NEW.original_person_mfn_id IS DISTINCT FROM OLD.original_person_mfn_id OR NEW.original_workspace_mfn_id IS DISTINCT FROM OLD.original_workspace_mfn_id OR NEW.acting_person_id IS DISTINCT FROM OLD.acting_person_id OR NEW.acting_person_mfn_id IS DISTINCT FROM OLD.acting_person_mfn_id OR NEW.represented_person_id IS DISTINCT FROM OLD.represented_person_id OR NEW.submission_source IS DISTINCT FROM OLD.submission_source OR NEW.source_mfn_id IS DISTINCT FROM OLD.source_mfn_id OR NEW.mfn_id IS DISTINCT FROM OLD.mfn_id THEN RAISE EXCEPTION 'Distribution source and audit identity are permanent'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_distribution_source BEFORE UPDATE ON public.trip_distributions FOR EACH ROW EXECUTE FUNCTION public.guard_distribution_source();
CREATE OR REPLACE FUNCTION public.guard_network_append_only() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Network history is append-only'; END $$;
CREATE TRIGGER network_history_append_only BEFORE UPDATE OR DELETE ON public.trip_offer_negotiations FOR EACH ROW EXECUTE FUNCTION public.guard_network_append_only();
CREATE TRIGGER network_events_append_only BEFORE UPDATE OR DELETE ON public.trip_network_events FOR EACH ROW EXECUTE FUNCTION public.guard_network_append_only();
CREATE OR REPLACE FUNCTION public.network_reservation_state(_trip uuid,_state text) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN t.network_provider_workspace_id IS NOT NULL AND t.network_status='reserved' AND t.status NOT IN ('completed','canceled','cancelled','no_show') THEN CASE WHEN t.pickup_date<current_date THEN 'past' ELSE 'unconfirmed' END ELSE _state END FROM public.trips t WHERE t.id=_trip $$;
REVOKE ALL ON FUNCTION public.network_reservation_state(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.network_reservation_state(uuid,text) TO authenticated,service_role;